parameters.jsCode:
const raw = $input.first().json.message?.content || '{}';
const trigger = $('TRIGGER — Webhook Lead Nuevo').first().json;
const enriched = $('ENRICH — Clearbit Company + Person').first().json;
let score;
try { score = JSON.parse(raw.match(/\{[\s\S]*\}/)?.[0] || raw); } catch(e) { score = { final_score: 0, classification: 'MQL', priority: 'LOW', recommended_action: 'SEQUENCE_NURTURE' }; }
score.lead_id = trigger.lead_id || `TRS01-${Date.now()}`;
score.email = trigger.email;
score.full_name = `${trigger.first_name || ''} ${trigger.last_name || ''}`.trim();
score.company = trigger.company || enriched?.company?.name || '';
score.job_title = trigger.job_title || enriched?.person?.employment?.title || '';
score.phone = trigger.phone || enriched?.person?.phone || '';
score.company_size = enriched?.company?.metrics?.employees || 'UNKNOWN';
score.company_revenue = enriched?.company?.metrics?.annualRevenue || null;
score.linkedin_url = enriched?.person?.linkedin?.handle ? `https://linkedin.com/in/${enriched.person.linkedin.handle}` : null;
score.response_time_target_minutes = score.classification === 'SQL' ? 5 : score.classification === 'MQL' ? 60 : 1440;
score.workflow_id = 'WF-TRS-01';
score.processed_at = new Date().toISOString();
return [{ json: score }];

